// Inicialización: mapa dispositivo -> zona (jerarquía de tópicos) y configuración de las APIs
const zones = {
  'dev-01': 'lote1', 'dev-02': 'lote1', 'dev-05': 'lote1', 'dev-06': 'lote1',
  'dev-03': 'clima', 'dev-04': 'clima',
  'dev-07': 'beneficio', 'dev-08': 'beneficio',
  'dev-09': 'historico', 'dev-10': 'historico'
};
global.set('zones', zones);
global.set('region', 'santander');
const base = { power: 'on', mode: 'auto', lat: Number(env.get('FARM_LAT') || 6.8817), lon: Number(env.get('FARM_LON') || -73.4103), last: 0, seq: 0, ok: 1 };
if (!flow.get('dev-03')) flow.set('dev-03', { ...base, interval_s: 600, name: 'Estación meteo exterior (Azure Maps Current Conditions)' });
if (!flow.get('dev-04')) flow.set('dev-04', { ...base, interval_s: 900, ahorro_agua: 1, name: 'Pronóstico de precipitación (Azure Maps Hourly Forecast)' });
// Al arrancar se fuerza una consulta inmediata de ambas APIs
const c3 = flow.get('dev-03'); c3.last = 0; flow.set('dev-03', c3);
const c4 = flow.get('dev-04'); c4.last = 0; flow.set('dev-04', c4);
node.status({ fill: 'green', shape: 'dot', text: 'inicializado' });
return [{ topic: 'dev-03', force: true }, { topic: 'dev-04', force: true }];

// Planificador de consultas a Azure Maps. Respeta el intervalo configurable por retroceso
// (SET_INTERVAL) y el encendido/apagado (POWER). msg.force = consulta inmediata (POLL_NOW).
const dev = msg.topic;
const cfg = flow.get(dev);
if (!cfg) return null;
const now = Date.now();
if (!msg.force && (cfg.power !== 'on' || now - cfg.last < cfg.interval_s * 1000)) return null;
const key = env.get('AZURE_MAPS_KEY');
if (!key || key.startsWith('pon-aqui')) { node.status({ fill: 'red', shape: 'ring', text: 'falta AZURE_MAPS_KEY' }); return null; }
cfg.last = now;
flow.set(dev, cfg);
const q = `${cfg.lat},${cfg.lon}`;
const base = 'https://atlas.microsoft.com/weather';
const out = { device: dev, method: 'GET', headers: { Accept: 'application/json' } };
out.url = dev === 'dev-03'
  ? `${base}/currentConditions/json?api-version=1.1&query=${q}&details=true&language=es-419&subscription-key=${key}`
  : `${base}/forecast/hourly/json?api-version=1.1&query=${q}&duration=12&language=es-419&subscription-key=${key}`;
node.status({ fill: 'blue', shape: 'dot', text: `${dev} consultado ${new Date().toISOString().slice(11, 19)}Z` });
return out;

// Normaliza la respuesta JSON de Azure Maps al contrato de telemetría CacaoSmart y genera el estado.
// Salida 1 -> telemetry (MQTT)   Salida 2 -> status retenido (MQTT)
const dev = msg.device;
const cfg = flow.get(dev);
const zone = 'clima';
const nowIso = new Date().toISOString().replace(/\.\d+Z$/, 'Z');
const t = (k) => `cacaosmart/santander/${zone}/${dev}/${k}`;
const v = (o) => (o && typeof o.value === 'number') ? o.value : null;

function buildStatus() {
  const s = { online: cfg.ok ? 1 : 0, device: dev, name: cfg.name, type: 'api', power: cfg.power, interval_s: cfg.interval_s,
              mode: cfg.mode, lat: cfg.lat, lon: cfg.lon, ts: nowIso, source: 'Azure Maps Weather v1.1' };
  if (dev === 'dev-04') s.ahorro_agua = cfg.ahorro_agua ? 1 : 0;
  if (cfg.error) s.error = cfg.error;
  if (cfg.last_cmd) s.last_cmd = cfg.last_cmd;
  return JSON.stringify(s);
}

if (msg.statusCode !== 200 || !msg.payload || typeof msg.payload !== 'object') {
  cfg.ok = 0; cfg.error = `HTTP ${msg.statusCode}`; flow.set(dev, cfg);
  node.status({ fill: 'red', shape: 'ring', text: cfg.error });
  return [null, { topic: t('status'), payload: buildStatus(), qos: 1, retain: true }];
}
cfg.seq = (cfg.seq || 0) + 1; cfg.ok = 1; delete cfg.error;
let tele;
if (dev === 'dev-03') {
  const r = msg.payload.results[0];
  const ps = r.precipitationSummary || {};
  tele = {
    ts: nowIso, type: 'api', seq: cfg.seq,
    temp_c: v(r.temperature), sensacion_c: v(r.realFeelTemperature), punto_rocio_c: v(r.dewPoint),
    hr_pct: r.relativeHumidity, uv_index: r.uvIndex, viento_kmh: v(r.wind && r.wind.speed),
    viento_dir_deg: r.wind && r.wind.direction ? r.wind.direction.degrees : null,
    rafaga_kmh: v(r.windGust && r.windGust.speed), nubosidad_pct: r.cloudCover, presion_hpa: v(r.pressure),
    visibilidad_km: v(r.visibility), lluvia_1h_mm: v(ps.pastHour) || 0, lluvia_24h_mm: v(ps.past24Hours) || 0,
    es_dia: r.isDayTime ? 1 : 0, condition: r.phrase
  };
} else {
  const f = msg.payload.forecasts || [];
  const f0 = f[0] || {};
  const prob = (x) => x.precipitationProbability || 0;
  tele = {
    ts: nowIso, type: 'api', seq: cfg.seq,
    prob_lluvia_pct: prob(f0),
    prob_lluvia_3h_pct: Math.max(0, ...f.slice(0, 3).map(prob)),
    prob_lluvia_max_12h: Math.max(0, ...f.map(prob)),
    precip_12h_mm: Math.round(f.reduce((s, x) => s + (v(x.totalLiquid) || 0), 0) * 10) / 10,
    horas_lluvia_12h: f.filter(x => x.hasPrecipitation).length,
    nubosidad_pct: f0.cloudCover, temp_prox_h_c: v(f0.temperature),
    uv_max_12h: Math.max(0, ...f.map(x => x.uvIndex || 0)),
    ahorro_agua: cfg.ahorro_agua ? 1 : 0, condition: f0.iconPhrase
  };
}
for (const k of Object.keys(tele)) if (tele[k] === null || tele[k] === undefined) delete tele[k];
flow.set(dev, cfg);
node.status({ fill: 'green', shape: 'dot', text: `${dev} #${cfg.seq}: ${tele.condition || ''}` });
return [{ topic: t('telemetry'), payload: JSON.stringify(tele), qos: 1, retain: true },
        { topic: t('status'), payload: buildStatus(), qos: 1, retain: true }];

// Retroceso para los dispositivos API (DEV-03, DEV-04): el "dispositivo" es la integración
// con Azure Maps, así que los comandos cambian cómo y cuándo se consulta la nube.
// Salida 1 -> status (ACK)  Salida 2 -> consulta inmediata
const dev = msg.topic.split('/')[3];
const cfg = flow.get(dev);
if (!cfg) return null;
const p = typeof msg.payload === 'object' ? msg.payload : {};
const cmd = String(p.cmd || p.action || '').toUpperCase();
let ok = true, txt = '', poll = false;
switch (cmd) {
  case 'SET_INTERVAL':
  case 'SET_POLLING': {
    // Azure Maps cobra por transacción: límite inferior de 60 s para no agotar la cuota
    const s = Math.max(60, Math.min(3600, Number(p.value || cfg.interval_s)));
    cfg.interval_s = s; txt = `polling cada ${s}s`; break;
  }
  case 'POWER':
    cfg.power = String(p.state || 'on').toLowerCase() === 'off' ? 'off' : 'on'; txt = `consultas ${cfg.power}`; break;
  case 'SET_LOCATION': {
    const lat = Number(p.lat), lon = Number(p.lon);
    if (isNaN(lat) || isNaN(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) { ok = false; txt = 'coordenadas inválidas'; break; }
    cfg.lat = lat; cfg.lon = lon; poll = true; txt = `ubicación ${lat},${lon}`; break;
  }
  case 'AHORRO_AGUA':
    if (dev !== 'dev-04') { ok = false; txt = 'sólo aplica a DEV-04'; break; }
    cfg.ahorro_agua = ['on', '1', 'true'].includes(String(p.state || 'on').toLowerCase()) ? 1 : 0;
    txt = `modo ahorro de agua ${cfg.ahorro_agua ? 'ACTIVO' : 'inactivo'}`; poll = true; break;
  case 'SET_MODE':
    cfg.mode = p.value === 'manual' ? 'manual' : 'auto'; txt = `modo ${cfg.mode}`; break;
  case 'POLL_NOW':
    poll = true; txt = 'consulta inmediata'; break;
  case 'PING':
    txt = 'pong'; break;
  default:
    ok = false; txt = `comando desconocido: ${cmd}`;
}
cfg.last_cmd = { cid: p.cid || '', cmd, src: p.src || 'desconocido', ok: ok ? 1 : 0, msg: txt, at: new Date().toISOString() };
flow.set(dev, cfg);
node.status({ fill: ok ? 'green' : 'red', shape: 'dot', text: `${dev} ${cmd}: ${txt}` });
const status = { online: cfg.ok ? 1 : 0, device: dev, name: cfg.name, type: 'api', power: cfg.power, interval_s: cfg.interval_s,
                 mode: cfg.mode, lat: cfg.lat, lon: cfg.lon, last_cmd: cfg.last_cmd, ts: new Date().toISOString() };
if (dev === 'dev-04') status.ahorro_agua = cfg.ahorro_agua;
return [{ topic: `cacaosmart/santander/clima/${dev}/status`, payload: JSON.stringify(status), qos: 1, retain: true },
        poll ? { topic: dev, force: true } : null];

// Guarda el último dato y el último estado de cada dispositivo (vista en memoria / "digital shadow")
const parts = msg.topic.split('/');
const dev = parts[3], kind = parts[4];
if (typeof msg.payload !== 'object' || msg.payload === null) return null;
const key = kind === 'telemetry' ? 'latest' : 'shadow';
const all = global.get(key) || {};
all[dev] = kind === 'telemetry' ? { at: Date.now(), data: msg.payload } : msg.payload;
global.set(key, all);
if (kind === 'status') {
  // Alerta de dispositivo fuera de línea (Last Will publicado por el broker)
  const prev = context.get('online') || {};
  const was = prev[dev];
  prev[dev] = msg.payload.online;
  context.set('online', prev);
  if (was === 1 && msg.payload.online === 0) {
    const zones = global.get('zones') || {};
    return { topic: `cacaosmart/santander/${zones[dev] || parts[2]}/${dev}/alert`, qos: 1,
             payload: JSON.stringify({ ts: new Date().toISOString(), rule: 'offline', severity: 'warning',
                                       msg: `${dev} perdió conexión con el broker (LWT)`, value: 0 }) };
  }
}
return null;

// =====================================================================
//  MOTOR DE REGLAS CacaoSmart IoT  (retroceso automático / lazos de control)
//  Se ejecuta con CADA mensaje de telemetría. Patrón de "reconciliación": compara el estado
//  deseado con el estado real reportado por el dispositivo (status retenido) y sólo envía
//  comandos cuando difieren, con tiempos de enfriamiento para evitar oscilaciones.
//
//  Lazo 1  Protección solar ......... UV (DEV-03) >= 8 -> polisombra DEV-05 al 80 % + LED DEV-01
//  Lazo 2  Riego predictivo ......... suelo DEV-02 < umbral -> consulta lluvia DEV-04 -> relé DEV-02 + bomba DEV-06
//  Lazo 4  Fermentación ............. masa DEV-07 > 50 °C o 48/96 h -> VOLTEO
//  Lazo 5  Secado ................... marquesina DEV-08 > 45 °C -> extractores + compuertas; lluvia -> cerrar
//  Alertas Moniliasis, fuga, sobrecalentamiento, desviación vs. curva ideal (DEV-10), anomalía DEV-09
//  (El Lazo 3, calibración remota, lo ejecuta el operador desde el panel o la API REST.)
//  Salida 1 -> comandos (MQTT .../command)   Salida 2 -> alertas (MQTT .../alert)
// =====================================================================
const p = msg.payload;
if (typeof p !== 'object' || p === null) return null;
const dev = msg.topic.split('/')[3];
const zones = global.get('zones') || {};
const latest = global.get('latest') || {};
const shadow = global.get('shadow') || {};
const st = context.get('st') || {};
const now = Date.now();
const cmds = [], alerts = [];
const iso = () => new Date().toISOString().replace(/\.\d+Z$/, 'Z');

function cmd(target, body) {
  const cid = 'r' + now.toString(36) + Math.floor(Math.random() * 1296).toString(36);
  cmds.push({ topic: `cacaosmart/santander/${zones[target]}/${target}/command`, qos: 1,
              payload: JSON.stringify({ ...body, src: 'rules', cid, ts: iso() }) });
}
function alert(target, rule, severity, text, value, cooldownMin) {
  const k = `al:${rule}:${target}`;
  if (st[k] && now - st[k] < (cooldownMin || 60) * 60000) return;
  st[k] = now;
  alerts.push({ topic: `cacaosmart/santander/${zones[target]}/${target}/alert`, qos: 1,
                payload: JSON.stringify({ ts: iso(), rule, severity, msg: text, value: Number(value) || 0 }) });
}
function cool(k, min) {               // true si ya pasó el enfriamiento (y lo reinicia)
  if (st[k] && now - st[k] < min * 60000) return false;
  st[k] = now; return true;
}
const data = (d) => (latest[d] && latest[d].data) || {};
const fresh = (d, maxMin) => !!latest[d] && now - latest[d].at < (maxMin || 30) * 60000;
const sh = (d) => shadow[d] || {};
const manual = (d) => sh(d).mode === 'manual';
const online = (d) => sh(d).online === 1;

switch (dev) {
  // ---------------------------------------------------------- LAZO 1: protección solar
  case 'dev-03': {
    const uv = Number(p.uv_index);
    let deseado = null;
    if (uv >= 8) deseado = 80;
    else if (uv <= 5) deseado = 30;                         // histéresis 5..8
    const actual = sh('dev-05').objetivo_pct;
    if (deseado !== null && online('dev-05') && !manual('dev-05') && actual !== deseado && cool('shade', 5)) {
      cmd('dev-05', { cmd: 'SET_SHADE', value: deseado });
      cmd('dev-01', { cmd: 'LED', state: deseado === 80 ? 'on' : 'off' });
      if (deseado === 80) alert('dev-03', 'uv_alto', 'warning', `Índice UV ${uv} ≥ 8: polisombra al 80 % y LED de aviso encendido`, uv, 180);
    }
    if (Number(p.temp_c) >= 34) alert('dev-03', 'calor_extremo', 'warning', `Temperatura exterior ${p.temp_c} °C: riesgo de estrés térmico en plántulas`, p.temp_c, 240);
    break;
  }
  // ---------------------------------------------------------- LAZO 2: riego predictivo
  case 'dev-02': {
    const h = Number(p.humedad_suelo_pct);
    const umbral = Number(p.umbral_pct || 35);
    if (h < umbral && !p.valvula && !manual('dev-02') && cool('riego', 45)) {
      const fc = data('dev-04');
      const prob = fresh('dev-04', 60) ? Number(fc.prob_lluvia_3h_pct ?? fc.prob_lluvia_pct) : null;
      const ahorro = sh('dev-04').ahorro_agua !== 0;
      if (prob !== null && prob > 65 && ahorro) {
        alert('dev-02', 'riego_inhibido', 'info', `Suelo ${h} % < ${umbral} %, pero lluvia ${prob} % > 65 %: riego bloqueado (ahorro hídrico)`, h, 60);
      } else {
        const mins = (prob === null || prob < 30) ? 15 : 8;   // lluvia incierta 30-65 % -> riego reducido
        cmd('dev-02', { cmd: 'RELAY', state: 'ON', duration_min: mins });
        cmd('dev-06', { cmd: 'START', duration_min: mins, flow: 30 });
        alert('dev-02', 'riego_auto', 'info', `Riego automático ${mins} min (suelo ${h} %, prob. lluvia ${prob === null ? 's/d' : prob + ' %'})`, h, 30);
      }
    }
    if (Number(p.bateria_v) > 0 && Number(p.bateria_v) < 3.5) alert('dev-02', 'bateria_baja', 'warning', `Batería del nodo ${p.bateria_v} V`, p.bateria_v, 360);
    break;
  }
  // ---------------------------------------------------------- Moniliasis (microclima)
  case 'dev-01': {
    const riesgo = Number(p.hr_pct) > 88 && Number(p.temp_c) > 26;
    if (riesgo) {
      st.monil = st.monil || now;
      const horas = (now - st.monil) / 3600000;
      if (horas >= 4) alert('dev-01', 'moniliasis', 'critical', `Riesgo de Moniliasis: HR > 88 % y T > 26 °C sostenidos ${horas.toFixed(1)} h`, p.hr_pct, 360);
    } else st.monil = null;
    break;
  }
  // ---------------------------------------------------------- Bomba (fugas)
  case 'dev-06': {
    if (Number(p.emergencia) === 1) alert('dev-06', 'fuga', 'critical', `Parada de emergencia de la bomba: presión ${p.presion_psi} PSI (posible fuga)`, p.presion_psi, 30);
    else if (Number(p.bomba) === 1 && Number(p.presion_psi) < 15) alert('dev-06', 'presion_baja', 'warning', `Presión de línea baja ${p.presion_psi} PSI`, p.presion_psi, 30);
    break;
  }
  // ---------------------------------------------------------- LAZO 4: fermentación
  case 'dev-07': {
    const t = Number(p.temp_masa_c), h = Number(p.horas_fermentacion), v = Number(p.volteos);
    if (!manual('dev-07')) {
      if (t > 50 && cool('volteo', 120)) {
        cmd('dev-07', { cmd: 'VOLTEO' });
        alert('dev-07', 'fermentacion_alta', 'warning', `Masa a ${t} °C (> 50 °C): volteo automático`, t, 120);
      } else if ((h >= 48 && v < 1) || (h >= 96 && v < 2)) {
        if (cool('volteo_prog', 60)) cmd('dev-07', { cmd: 'VOLTEO' });
      }
    }
    if (h > 60 && h < 110 && t < 35) alert('dev-07', 'fermentacion_fria', 'warning', `Fermentación fría (${t} °C en fase acética): revisar masa`, t, 240);
    break;
  }
  // ---------------------------------------------------------- LAZO 5: secado
  case 'dev-08': {
    const t = Number(p.temp_interna_c);
    const lluvia = Number(data('dev-03').lluvia_1h_mm || 0) > 0 ||
                   (fresh('dev-04', 60) && Number(data('dev-04').prob_lluvia_pct) >= 65);
    let ext = Number(p.extractores), comp = Number(p.compuertas);
    let extD = ext, compD = comp;
    if (t > 45) { extD = 1; compD = 1; }
    else if (t < 40) extD = 0;
    if (t <= 45) compD = lluvia ? 0 : 1;
    if (!manual('dev-08')) {
      if (extD !== ext && cool('ext', 5)) cmd('dev-08', { cmd: 'EXTRACTORES', state: extD ? 'on' : 'off' });
      if (compD !== comp && cool('comp', 5)) cmd('dev-08', { cmd: 'COMPUERTAS', state: compD ? 'open' : 'close' });
    }
    if (t > 46) alert('dev-08', 'sobrecalentamiento', 'critical', `Marquesina a ${t} °C (> 46 °C): riesgo de acidez y grano arrebatado`, t, 60);
    const ideal = data('dev-10');
    if (fresh('dev-10', 30) && ideal.humedad_objetivo_pct !== undefined) {
      const desv = Number(p.humedad_grano_pct) - Number(ideal.humedad_objetivo_pct);
      if (desv > 8) alert('dev-08', 'secado_retrasado', 'info', `Grano ${desv.toFixed(1)} pts por encima de la curva ideal (${ideal.profile})`, desv, 360);
    }
    if (Number(p.humedad_grano_pct) <= 7) alert('dev-08', 'lote_listo', 'info', `Lote #${p.lote} seco: ${p.humedad_grano_pct} % (≤ 7 %, NTC 1252)`, p.humedad_grano_pct, 720);
    break;
  }
  // ---------------------------------------------------------- Dataset: anomalía inyectada
  case 'dev-09': {
    if (Number(p.anomalia) === 1) alert('dev-09', 'anomalia_dataset', 'warning', `Anomalía térmica inyectada en el histórico: ${p.temp_ref_c} °C`, p.temp_ref_c, 30);
    const actual = data('dev-03').temp_c;
    if (actual !== undefined && fresh('dev-03', 30) && Math.abs(Number(actual) - Number(p.temp_ref_c)) > 6)
      alert('dev-09', 'desviacion_historica', 'info', `Temperatura actual ${actual} °C vs ${p.temp_ref_c} °C hace un año`, Number(actual) - Number(p.temp_ref_c), 360);
    break;
  }
}
context.set('st', st);
if (cmds.length || alerts.length) node.status({ fill: 'yellow', shape: 'dot', text: `${dev}: ${cmds.length} cmd, ${alerts.length} alertas` });
return [cmds, alerts];

// Notificación de alertas warning/critical a Telegram (opcional: TELEGRAM_BOT_TOKEN y TELEGRAM_CHAT_ID en .env)
const token = env.get('TELEGRAM_BOT_TOKEN'), chat = env.get('TELEGRAM_CHAT_ID');
if (!token || !chat) return null;
const a = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
if (!['warning', 'critical'].includes(a.severity)) return null;
const dev = msg.topic.split('/')[3];
const icon = a.severity === 'critical' ? '🚨' : '⚠️';
return {
  url: `https://api.telegram.org/bot${token}/sendMessage`, method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  payload: { chat_id: chat, text: `${icon} CacaoSmart · ${dev.toUpperCase()}\n${a.msg}` }
};

// API REST de CacaoSmart (endpoints HTTP sobre Node-RED, publicados por Caddy en https://<dominio>/api/...)
//   POST /api/ingest/:device            ingesta de telemetría por HTTP (DEV-10)      [Bearer API_TOKEN]
//   POST /api/devices/:device/command   envía un comando de retroceso                [Bearer API_TOKEN]
//   GET  /api/devices                   último dato + estado de los 10 dispositivos  [público]
//   GET  /api/health                    estado del servicio                           [público]
// Salida 1 -> MQTT   Salida 2 -> respuesta HTTP
const zones = global.get('zones') || {};
const route = msg.req.route.path;
const method = msg.req.method;
const res = (code, body) => [null, { ...msg, statusCode: code, payload: body, headers: { 'Content-Type': 'application/json' } }];
const authed = (msg.req.headers.authorization || '') === `Bearer ${env.get('API_TOKEN')}`;

if (route === '/api/health') {
  return res(200, { ok: true, service: 'cacaosmart-nodered', time: new Date().toISOString(), devices: Object.keys(zones).length });
}
if (route === '/api/devices' && method === 'GET') {
  const latest = global.get('latest') || {}, shadow = global.get('shadow') || {};
  const out = {};
  for (const d of Object.keys(zones).sort()) {
    out[d] = { zone: zones[d], status: shadow[d] || null, last: latest[d] ? latest[d].data : null,
               last_seen_s: latest[d] ? Math.round((Date.now() - latest[d].at) / 1000) : null };
  }
  return res(200, out);
}
if (!authed) return res(401, { error: 'token inválido o ausente (Authorization: Bearer <API_TOKEN>)' });

const dev = msg.req.params.device;
if (!zones[dev]) return res(404, { error: `dispositivo desconocido: ${dev}` });
const body = typeof msg.payload === 'object' && msg.payload !== null ? msg.payload : null;
if (!body) return res(400, { error: 'se esperaba un cuerpo JSON' });

if (route === '/api/ingest/:device') {
  body.ts = body.ts || new Date().toISOString().replace(/\.\d+Z$/, 'Z');
  const topic = `cacaosmart/santander/${zones[dev]}/${dev}/telemetry`;
  node.status({ fill: 'green', shape: 'dot', text: `ingest ${dev} #${body.seq || ''}` });
  return [{ topic, payload: JSON.stringify(body), qos: 1 }, { ...msg, statusCode: 202, payload: { accepted: true, topic } }];
}
if (route === '/api/devices/:device/command') {
  if (!body.cmd) return res(400, { error: 'falta el campo "cmd"' });
  const cid = body.cid || ('a' + Date.now().toString(36));
  const out = { ...body, cmd: String(body.cmd).toUpperCase(), cid, src: 'api', ts: new Date().toISOString() };
  const topic = `cacaosmart/santander/${zones[dev]}/${dev}/command`;
  node.status({ fill: 'blue', shape: 'dot', text: `cmd ${dev} ${out.cmd}` });
  return [{ topic, payload: JSON.stringify(out), qos: 1 }, { ...msg, statusCode: 202, payload: { sent: true, cid, topic, command: out } }];
}
return res(404, { error: 'ruta no encontrada' });
